/**
 * Stable failure categories crossing the native-language boundary.
 *
 * Messages are deliberately safe to surface. They never include key material,
 * raw PSBTs, invoices, or backend payloads.
 */
package 
enum SignerError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidArgument(reason: String
    )
    case InvalidMnemonic
    case InvalidSeed
    case EntropyUnavailable
    case InvalidNetwork(reason: String
    )
    case InvalidPsbt(reason: String
    )
    case PolicyRejected(reason: String
    )
    case KeyDerivation
    case SigningFailed
    case SignatureVerification

    

    

    
    package var errorDescription: String? {
        String(reflecting: self)
    }
    
}

