@_documentation(visibility: private)
#endif
package struct FfiConverterTypeSignerError: FfiConverterRustBuffer {
    typealias SwiftType = SignerError

    package static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SignerError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidArgument(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidMnemonic
        case 3: return .InvalidSeed
        case 4: return .EntropyUnavailable
        case 5: return .InvalidNetwork(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .InvalidPsbt(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .PolicyRejected(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 8: return .KeyDerivation
        case 9: return .SigningFailed
        case 10: return .SignatureVerification

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    package static func write(_ value: SignerError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidArgument(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .InvalidMnemonic:
            writeInt(&buf, Int32(2))
        
        
        case .InvalidSeed:
            writeInt(&buf, Int32(3))
        
        
        case .EntropyUnavailable:
            writeInt(&buf, Int32(4))
        
        
        case let .InvalidNetwork(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .InvalidPsbt(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .PolicyRejected(reason):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .KeyDerivation:
            writeInt(&buf, Int32(8))
        
        
        case .SigningFailed:
            writeInt(&buf, Int32(9))
        
        
        case .SignatureVerification:
            writeInt(&buf, Int32(10))
        
        }
    }
}


